Hi Brian, thanks for dropping us a line.

If your use case is simple enough, this kind of thing can work:

```csharp
class SwitchableSink : ILogEventSink, IDisposable
{
    readonly object _sync = new();
    readonly ILogEventSink? _instance = null;

    public void Emit(LogEvent logEvent)
    {
        lock (_sync)
        {
             _instance?.Emit(logEvent);
        }
    }

    public IDisposable Set(Action<LoggerSinkConfiguration> configure)
    {
        lock (_sync)
        {
             (_instance as IDisposable)?.Dispose();
             var instance = _instance = LoggerSinkConfiguration.CreateSink(configure);
             return new UnsetOnDispose(() => Unset(instance));
        }
    }

    sealed class UnsetOnDispose(Action onDispose): IDisposable
    {
        public void Dispose() => onDispose();
    }

    void Unset(ILogEventSink instance)
    {
        lock (_sync)
        {
             if (_instance != instance) return;
             (_instance as IDisposable)?.Dispose();
             _instance = null;
        }
    }

    public void Dispose()
    {
        lock (_sync)
        {
             (_instance as IDisposable)?.Dispose();
             _instance = null;
        }
    }
}
```

Usage:

```csharp
// Put this somewhere accessible: static field, IoC container, etc.
var switchable = new SwitchableSink();

Log.Logger = new LoggerConfiguration()
    .WriteTo.Sink(switchable)
    .CreateLogger();

// Later
using (var extraSink = switchable.Set(wt => wt.Console()))
{
    Log.Information("Extra sink is active");
}
```

The synchronization you can see in `SwitchableSink` is one of the main reasons for avoiding mutability in the sink collection.

