### ServiceEnricher
Although not listed in the original comment, we have another enricher to set properties about the service which generated the logs.
```
internal class ServiceEnricher : ILogEventEnricher
{
  internal LogEventProperty serviceName;
  internal LogEventProperty serviceEnvironment;
  internal LogEventProperty serviceVersion;

  public void Enrich(LogEvent logEvent, ILogEventPropertyFactory propertyFactory)
  {
    LogEventProperty serviceNameProperty = serviceName;
    LogEventProperty serviceEnvironmentProperty = serviceEnvironment;
    LogEventProperty serviceVersionProperty = serviceVersion;

    if (serviceNameProperty is null)
    {
      serviceNameProperty = serviceName = propertyFactory.CreateProperty(
        "service.name",
        Environment.GetEnvironmentVariable("SERVICE_NAME"));
    }

    if (serviceEnvironmentProperty is null)
    {
      serviceEnvironmentProperty = serviceEnvironment = propertyFactory.CreateProperty(
        "service.environment",
        Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT"));
    }

    if (serviceVersionProperty is null)
    {
      serviceVersionProperty = serviceVersion = propertyFactory.CreateProperty(
        "service.version",
        Assembly.GetEntryAssembly().GetName().Version.ToString());
    }

    if (serviceNameProperty != null)
    {
      logEvent.AddPropertyIfAbsent(serviceNameProperty);
    }

    if (serviceEnvironmentProperty != null)
    {
      logEvent.AddPropertyIfAbsent(serviceEnvironmentProperty);
    }

    if (serviceVersionProperty != null)
    {
      logEvent.AddPropertyIfAbsent(serviceVersionProperty);
    }
  }
}
```

### EcsTextFormattingMapper
Since the properties were being nested under `metadata`, we tried implementing a custom formatting mapper to see if there was some issue converting from log messages to the Elastic document.
```
internal static class EcsTextFormattingMapper
{

  internal static Elastic.CommonSchema.Base Map(Elastic.CommonSchema.Base doc, LogEvent logEvent)
  {
    TryAddDocumentService(doc, logEvent);
    TryAddDocumentLabel<int>(doc, logEvent, "partition");
    TryAddDocumentLabel<string>(doc, logEvent, "service.environment");
  }

  internal static void TryAddDocumentService(Elastic.CommonSchema.Base doc, LogEvent logEvent)
  {
    if (doc.Service is null)
    {
      doc.Service = new Elastic.CommonSchema.Service();
    }

    doc.Service.Name = (string) (ScalarValue) logEvent.Properties["service.name"]).Value;
    doc.Service.Version = (string) (ScalarValue) logEvent.Properties["service.environment"]).Value;
  }

  internal static void TryAddDocumentLabel<T>(Elastic.CommonSchema.Base doc, LogEvent logEvent, string propertyName)
  {
    if (doc.Labels is null)
    {
      doc.Labels = new Dictionary<string, object>();
    }

    doc.Labels[propertyName] = (T) ((ScalarValue) logEvent.Properties[propertyName]).Value;
  }
}
```

