Here is my final solution, I had to use a middleware...

```csharp
public class SerilogMiddleware
{
    private readonly RequestDelegate _next;

    private readonly PathString[] _paths = new[] {
        new PathString("/health"),
        new PathString("/healthchecks-api"),
    };

    public SerilogMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var path = context.Request.Path;

        if (_paths.Contains(path.Value))
        {
            using (LogContext.PushProperty("VoidLogging", value: true))
            {
                await _next(context).ConfigureAwait(false);
            }
        }
        else
        {
            await _next(context).ConfigureAwait(false);
        }
    }
}
