```c#

#nullable enable
using System;
using System.Collections.Generic;
using System.IO;
using Serilog.Events;

namespace Serilog.Formatting.Json
{
    /// <summary>
    /// Formats log events into JSON text using configurable property mappings.
    /// </summary>
    public class MappedJsonFormatter : JsonValueFormatter, ITextFormatter
    {
        /// <summary>
        /// Intializes a new instance of <see cref="MappedJsonFormatter"/>.
        /// </summary>
        /// <param name="typeTagName">
        /// The JSON property name for <see cref="StructureValue.TypeTag"/> values. Default is "_typeTag."
        /// </param>
        public MappedJsonFormatter(string? typeTagName = DefaultTypeTagName) : base(typeTagName)
        {
        }

        /// <summary>
        /// The collection of delegates used to select and/or build properties for each log event.
        /// </summary>
        /// <remarks>
        /// Use <see cref="AddStandardMappings"/> to populate with default mappings.
        /// </remarks>
        public IList<Func<LogEvent, LogEventProperty>> PropertyMappings { get; }
            = new List<Func<LogEvent, LogEventProperty>>();

        /// <summary>
        /// Adds standard mappings for timestamp, level, message, exception, and/or properties to <see cref="PropertyMappings"/>.
        /// </summary>
        /// <param name="timestampName">The JSON property name for the timestamp, or <see langword="null"/> to skip.</param>
        /// <param name="levelName">The JSON property name for the level, or <see langword="null"/> to skip.</param>
        /// <param name="messageName">The JSON property name for the message, or <see langword="null"/> to skip.</param>
        /// <param name="exceptionName">The JSON property name for the exception, or <see langword="null"/> to skip.</param>
        /// <param name="propertiesName">The JSON property name for the properties, or <see langword="null"/> to skip.</param>
        /// <returns>The same formatter instance, for chaining.</returns>
        public MappedJsonFormatter AddStandardMappings(
            string? timestampName = "Timestamp",
            string? levelName = "Level",
            string? messageName = "Message",
            string? exceptionName = "Exception",
            string? propertiesName = "Properties")
        {
            if (messageName != null)
            {
                PropertyMappings.Add(ev => new(messageName, new ScalarValue(ev.RenderMessage())));
            }

            if (timestampName != null)
            {
                PropertyMappings.Add(ev => new(timestampName, new ScalarValue(ev.Timestamp)));
            }

            if (levelName != null)
            {
                PropertyMappings.Add(ev => new(levelName, new ScalarValue(ev.Level)));
            }

            if (exceptionName != null)
            {
                PropertyMappings.Add(ev => new(exceptionName, new ScalarValue(ev.Exception)));
            }

            if (propertiesName != null)
            {
                PropertyMappings.Add(ev => new(propertiesName, new StructureValue(MapProperties(ev.Properties))));

                static IEnumerable<LogEventProperty> MapProperties(
                    IEnumerable<KeyValuePair<string, LogEventPropertyValue>> properties)
                {
                    foreach (var (key, value) in properties)
                    {
                        yield return new(key, value);
                    }
                }
            }

            return this;
        }

        /// <inheritdoc />
        public void Format(LogEvent logEvent, TextWriter output)
        {
            if (logEvent == null) throw new ArgumentNullException(nameof(logEvent));
            if (output == null) throw new ArgumentNullException(nameof(output));

            Format(new StructureValue(GetProperties(logEvent)), output);
        }

        IEnumerable<LogEventProperty> GetProperties(LogEvent logEvent)
        {
            foreach (var mapping in PropertyMappings)
            {
                yield return mapping(logEvent);
            }
        }
    }
}
```

