@nblumhardt this seems to do the trick manually testing locally. Hopefully I'll be able to open a PR soon, but for now here it is:

```cs
internal class DictionaryDestructurePolicy : IDestructuringPolicy
{
    private readonly Func<object, bool> _destructurePredicate;

    public DictionaryDestructurePolicy(Func<object, bool> destructurePredicate)
    {
        _destructurePredicate = destructurePredicate;
    }

    public bool TryDestructure(object value, ILogEventPropertyValueFactory propertyValueFactory, out LogEventPropertyValue result)
    {
        if (value == null || _destructurePredicate(value) == false || value is not IDictionary asDictionary)
        {
            result = null;
            return false;
        }

        var elements = new List<KeyValuePair<ScalarValue, LogEventPropertyValue>>();

        foreach (var item in asDictionary.Keys)
        {
            var logEventPropertyValue = propertyValueFactory.CreatePropertyValue(asDictionary[item], true);
            elements.Add(new KeyValuePair<ScalarValue, LogEventPropertyValue>(new ScalarValue(item), logEventPropertyValue));
        }

        result = new DictionaryValue(elements);
        return true;
    }
}
```

```cs
public static class DictionaryDestructurePolicyExtensions
{
    public static LoggerConfiguration AsDictionaryWhere(this LoggerDestructuringConfiguration config, Func<object, bool> destructurePredicate)
    {
        return config.With(new DictionaryDestructurePolicy(destructurePredicate));
    }

    public static LoggerConfiguration AsDictionaryAssignableTo<TValue>(this LoggerDestructuringConfiguration config)
    {
        return config.AsDictionaryWhere(obj => obj is TValue);
    }

    public static LoggerConfiguration AsDictionary<TValue>(this LoggerDestructuringConfiguration config)
    {
        return config.AsDictionaryWhere(obj => obj.GetType() == typeof(TValue));
    }

    public static LoggerConfiguration AllDictionaryTypesAsStructured(this LoggerDestructuringConfiguration config)
    {
        return config.AsDictionaryWhereAssignableTo<IDictionary>();
    }
}
