In case anyone searches for similar, I solved this by adding filtering where

`.Filter.ByIncludingOnly(Matching.FromSource<Window>())` can be used to filter based on one or more sources. This is useful for general logging from one or more classes.

and

`.Filter.ByIncludingOnly("Contains(Filename , 'serilogData')")` can be used to filter expression based on the ForContext variable, in this case I have a known folder name `serilogData` being passed in `Filename`

Full code below
```

    public partial class Window
    {
        public Window()
        {
            InitializeComponent();

            string serilogSystem = @"...\Desktop\serilogSystem\test.log";

            Log.Logger = new LoggerConfiguration()
            .MinimumLevel.Debug()

            // INCLUDE only Matching.FromSource<Window>()
            .WriteTo.Logger(lc => lc
                .Filter.ByIncludingOnly(Matching.FromSource<Window>())
                .WriteTo.File(serilogSystem,
                            outputTemplate: "[{Timestamp:yyyy-MM-dd HH:mm:ss.fff zzz} {Level:u3}] {Message:lj} {Exception} {NewLine}",
                            flushToDiskInterval: TimeSpan.FromSeconds(1),
                            rollingInterval: RollingInterval.Day,
                            rollOnFileSizeLimit: true,
                            encoding: Encoding.UTF8))

            // INCLUDE only logs where ForContext Filename parameter contains 'serilogData' (ie filtering by known folder name)
            .WriteTo.Logger(lc => lc
                .Filter.ByIncludingOnly("Contains(Filename , 'serilogData')")
                .WriteTo.Map("Filename", @"C:\log.txt", (filename, wt) => wt.File(filename,
                            outputTemplate: "{Message}{NewLine}",
                            flushToDiskInterval: TimeSpan.FromSeconds(1),
                            encoding: Encoding.UTF8)))
            .CreateLogger();

            SystemLogger();
            var customLogger = new CustomLogger();
            customLogger.LogData("This is some data to log", "1.txt");

            Log.CloseAndFlush();
        }

        private void SystemLogger()
