                Log.ForContext<Window>().Information("General System log information.");
                Log.ForContext<Window>().Debug("General System log debug.");

                int a = 0;
                int b = 0;
                int c = a / b;
            }
            catch(Exception ex)
            {
                Log.ForContext<Window>().Error(ex, "SystemLogger() Error");
            }
        }

    }

    public class CustomLogger
    {
