```
    /// <summary>
    /// this formatter wrapps the default implementation and omits stacktraces for the filtered exceptions
    /// </summary>
    public class OmitStacktraceFormatter : ITextFormatter
    {
        private readonly ITextFormatter _inner;
        private readonly Func<Exception, bool> _exceptionFilter;

        public OmitStacktraceFormatter(ITextFormatter inner, Func<Exception, bool> exceptionFilter)
        {
            _inner = inner;
            _exceptionFilter = exceptionFilter;
        }

        private readonly MessageTemplateParser _parser = new MessageTemplateParser();

        public void Format(LogEvent logEvent, TextWriter output)
        {
            if (_exceptionFilter(logEvent.Exception))
            {
                logEvent = new LogEvent(logEvent.Timestamp, logEvent.Level, null, _parser.Parse(logEvent.MessageTemplate.Text + "{"+ nameof(logEvent.Exception) + "}"), logEvent.Properties
                    .Select(p => new LogEventProperty(p.Key, p.Value)).Concat(new []
                    {
                        new LogEventProperty(nameof(logEvent.Exception), new ScalarValue(logEvent.Exception.Message)), 
                    }));
            }

            _inner.Format(logEvent, output);
        }
    }
```

