@CreepyGnome you can also use dumb private source context combined with minimum level overrides without the risk of getting more log events than needed:
```csharp
class Program
{
    static void Main(string[] args)
    {
        var logger = new LoggerConfiguration()
                .MinimumLevel.Warning()
                .MinimumLevel.Override(typeof(Startup).FullName, LogEventLevel.Information)
                .WriteTo.Console()
                .CreateLogger();

        logger.LogStartup();

        // ...
        logger.Information("invisible");
        // ...

        logger.LogShutdown();
    }

}

class Startup { }

static class LogExtensions
{
    public static void LogStartup(this ILogger logger)
        => logger.ForContext<Startup>().Information("service started");

    public static void LogShutdown(this ILogger logger)
        => logger.ForContext<Startup>().Information("service shutted down");
