@osudude, you can inject IHttpContextAccessor in enrichers. Maybe we were'nt able to do it in the past but with Net Core 3.1, I'm doing this:

```
public class RemoteIpAddressEnricher : ILogEventEnricher
{
    private const string RemoteIpAddressPropertyName = "RemoteIpAddress";
    private const string RemoteIpAddressPropertyCacheName = "Serilog.Enrichers.AspnetCore.RemoteIpAddressEnricher";
    private IHttpContextAccessor _httpContextAccessor;

    public RemoteIpAddressEnricher()
        : this(new HttpContextAccessor())
    {
    }

    public RemoteIpAddressEnricher(IHttpContextAccessor httpContextAccessor)
    {
        this._httpContextAccessor = httpContextAccessor;
    }

    public void Enrich(LogEvent logEvent, ILogEventPropertyFactory propertyFactory)
    {
        var httpContext = _httpContextAccessor.HttpContext;

        if (httpContext == null)
        {
            return;
        }

        var remoteIpAddressPropertyCache = httpContext.Items[RemoteIpAddressPropertyCacheName] as LogEventProperty;

        if (remoteIpAddressPropertyCache == null)
        {
            remoteIpAddressPropertyCache = CreateProperty(propertyFactory, httpContext);
            httpContext.Items[RemoteIpAddressPropertyCacheName] = remoteIpAddressPropertyCache;
        }

        logEvent.AddPropertyIfAbsent(remoteIpAddressPropertyCache);
    }

    private LogEventProperty CreateProperty(ILogEventPropertyFactory propertyFactory, HttpContext httpContext)
    {
        var remoteIpAddress = httpContext.Connection.RemoteIpAddress;
        var remoteIpAdresseProperty = propertyFactory.CreateProperty(RemoteIpAddressPropertyName, remoteIpAddress);

        return remoteIpAdresseProperty;
    }
}
```

