I have made two examples that make it obvious that in .net core 2.0 AsyncLocal makes a copy of the data for each task, and that it doesn't flow back changes to the parent:
```
using System;
using System.Threading;
using System.Threading.Tasks;

namespace SerilogAsyncLocalBug
{
    class Program
    {
        private static readonly AsyncLocal<string> AsyncLocalWithOverwrite = new AsyncLocal<string>();

        static async Task Main(string[] args)
        {
            await AsyncMethod1();
            Console.WriteLine($"No contextual properties. LocalProperties.Value == null = {AsyncLocalWithOverwrite.Value == null}"); // localProperties.Value throws NullReferenceException here
        }

        private static async Task AsyncMethod1()
        {
            Console.WriteLine($"No contextual properties. LocalProperties.Value == null = {AsyncLocalWithOverwrite.Value == null}"); // localProperties.Value throws NullReferenceException here

            AsyncLocalWithOverwrite.Value = "A=1";
            Console.WriteLine($"Carries property A = 1: {AsyncLocalWithOverwrite.Value}");

            await AsyncMethod2();
            Console.WriteLine($"Carries A = 1: {AsyncLocalWithOverwrite.Value}");
        }

        private static async Task AsyncMethod2()
        {
            await Task.Delay(50);
            AsyncLocalWithOverwrite.Value = "A=1, B=1";
            Console.WriteLine($"Carries A = 1 and B = 1 {AsyncLocalWithOverwrite.Value}");
        }
    }
}
```
Of course, using a mutable referenced class, and changing that, does flow back changes to the parent:
```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace SerilogAsyncLocalBug
{
    class Program
    {
        private static readonly AsyncLocal<List<string>> AsyncLocalWithReference = new AsyncLocal<List<string>>();

        static async Task Main(string[] args)
        {
            await AsyncMethod1();
            Console.WriteLine($"No contextual properties. LocalProperties.Value == null = {AsyncLocalWithReference.Value == null}"); // localProperties.Value throws NullReferenceException here
        }

        private static async Task AsyncMethod1()
        {
            Console.WriteLine($"No contextual properties. LocalProperties.Value == null = {AsyncLocalWithReference.Value == null}"); // localProperties.Value throws NullReferenceException here

            AsyncLocalWithReference.Value = new List<string> {"A=1"};
            Console.WriteLine($"Carries property A = 1: {AsyncLocalWithReference.Value.Aggregate((a, b) => a + b)}");

            await AsyncMethod2();
            Console.WriteLine($"Carries A = 1 and B = 1: {AsyncLocalWithReference.Value.Aggregate((a, b) => a + b)}");
        }

        private static async Task AsyncMethod2()
        {
            await Task.Delay(50);
            AsyncLocalWithReference.Value.Add("B=1");
            Console.WriteLine($"Carries A = 1 and B = 1 {AsyncLocalWithReference.Value.Aggregate((a, b) => a + b)}");
        }
    }
}
```

