	public ConfigBuilder()
	{
		_sources = new List<IEnumerable<KeyValuePair<string, string>>>();
	}

	public IEnumerable<KeyValuePair<string, string>> BuildCombinedEnumerable()
	{
		IEnumerable<KeyValuePair<string, string>> Combined()
		{
