				{
					result[kvp.Key] = kvp.Value;
				}
			}
			return result;
		}

		foreach (var kvp in Combined())
		{
			yield return kvp;
		}
	}

	public IConfigBuilder AddSource(IEnumerable<KeyValuePair<string, string>> source)
	{
		_sources.Add(source);
		return this;
	}
