@tiesmaster  and anyone else comes across this and is used to the MappedDiagnosticsContext from NLog, here is dictionary implementation for storing whatever you might need:

```
using Serilog.Context;
using System;
using System.Collections.Immutable;
using System.Threading;

namespace Core.Logging
{
    public static class ContextCorrelator
    {
        private static AsyncLocal<ImmutableDictionary<string, object>> _items = new AsyncLocal<ImmutableDictionary<string, object>>();
        private static ImmutableDictionary<string,object> Items
        {
            get => _items.Value == null ? _items.Value = ImmutableDictionary<string, object>.Empty : _items.Value;
            set => _items.Value = value;
        }

        public static object GetValue(string key) => Items[key];

        public static IDisposable BeginCorrelationScope(string key, object value)
        {
            if (Items.ContainsKey(key))
            {
                throw new InvalidOperationException($"{key} is already being correlated!");
            }

            Items = Items.Add(key, value);
            return new CorrelationScope(LogContext.PushProperty(key, value));
        }

        public class CorrelationScope : IDisposable
        {
            readonly IDisposable _logContextPop;

            public CorrelationScope(IDisposable logContextPop)
            {
                _logContextPop = logContextPop ?? throw new ArgumentNullException(nameof(logContextPop));
            }

            public void Dispose() => _logContextPop.Dispose();
        }
    }
}
```

You can then use as:

```
using (ContextCorrelator.BeginCorrelationScope("SessionId", sessionId))
{
    var sessionId = ContextCorrelator.GetValue("SessionId");
}
```

