This is how I use it. (Based on [this](https://github.com/structuremap/structuremap/issues/459#issuecomment-261840837) comment)
```csharp
using System;
using System.Linq;
using System.Reflection;
using Serilog;
using StructureMap;
using StructureMap.Pipeline;

namespace Services.Logging
{
    public class LoggingRegistry : Registry
    {
        public LoggingRegistry()
        {
            For<ILogger>().Use(() => Configuration.Logger);
            Policies.Add<SerilogPolicy>();
        }

        public class SerilogPolicy : ConfiguredInstancePolicy
        {
            protected override void apply(Type pluginType, IConfiguredInstance instance)
            {
                ParameterInfo parameter = instance.Constructor?.GetParameters().Where(x => x.ParameterType == typeof(ILogger)).FirstOrDefault();
                if (parameter != null)
                {
                    ILogger logger = Configuration.Logger.ForContext(pluginType);
                    instance.Dependencies.AddForConstructorParameter(parameter, logger);
                }
                else
                {
                    PropertyInfo property = instance.SettableProperties().Where(x => x.PropertyType == typeof(ILogger)).FirstOrDefault();
                    if (property != null)
                    {
                        ILogger logger = Configuration.Logger.ForContext(pluginType);
                        instance.Dependencies.AddForProperty(property, logger);
                    }
                }
            }
        }
    }
}
```

Note: I have a `static Configuration.Logger` with a Serilog logger configured.
