using System;
using System.Runtime.Remoting.Lifetime;
using System.Threading;

using Serilog;
using Serilog.Context;
using Serilog.Core;
using Serilog.Events;

namespace SerilogIssue
{
    class Program
    {
        static void Main(string[] args)
        {
            LifetimeServices.LeaseTime = TimeSpan.FromMilliseconds(200);
            LifetimeServices.LeaseManagerPollTime = TimeSpan.FromMilliseconds(100);

            AppDomain.CurrentDomain.FirstChanceException += (_, e)
                => Console.WriteLine("First chance exception: " + e.Exception.Message);

            Log.Logger = new LoggerConfiguration()
                .Enrich.FromLogContext()
                .AuditTo.Sink<ConsoleSink>()
                .CreateLogger();

            var remote = AppDomain.CreateDomain("Remote", null, null);

            using (LogContext.PushProperty("Prop", 42))
            {
                remote.DoCallBack(CallFromRemote);

                // throws exception and swallows despite `Audit` setting;
                // after prints unenriched template 'Prop = {Prop}'
                Log.Information("Prop = {Prop}");
            }

            Console.ReadLine();
        }

        static void CallFromRemote() => Thread.Sleep(400);
    }

    class ConsoleSink : ILogEventSink
    {
        public void Emit(LogEvent logEvent) => logEvent.RenderMessage(Console.Out);
    }
}
