Here's what we did. If it's something you want, I can PR it or whatever. Yours for the taking, and thanks again for the help.

``` csharp
using System;
using System.Linq;
using System.Threading;
using Microsoft.Extensions.Configuration;
using Serilog.Core;
using Serilog.Events;

namespace ProjectNamespace
{
    /// <summary>
    /// Log level switch that periodically updates based on a configuration setting.
    /// </summary>
    /// <seealso cref="Serilog.Core.LoggingLevelSwitch" />
    /// <seealso cref="System.IDisposable" />
    public class ConfigurableLoggingLevelSwitch : LoggingLevelSwitch, IDisposable
    {
        /// <summary>
        /// Flag indicating whether the object has been disposed.
        /// </summary>
        private bool _isDisposed = false;

        /// <summary>
        /// The timer used for periodic updating of the switch value.
        /// </summary>
        private Timer _updateTimer;

        /// <summary>
        /// Create a <see cref="ConfigurableLoggingLevelSwitch"/> at the initial
        /// minimum level.
        /// </summary>
        /// <param name="configuration">
        /// The configuration key where the log level is set. The value at this
        /// node will be parsed into a <see cref="LogEventLevel"/> and update
        /// the switch value.
        /// </param>
        /// <param name="updateIntervalMilliseconds">
        /// The interval at which the <paramref name="configuration" /> should be read
        /// so the <see cref="LoggingLevelSwitch.MinimumLevel"/> can be updated.
        /// </param>
        /// <param name="defaultLevel">
        /// The default level for the switch when the value in <paramref name="configuration" />
        /// isn't found or can't be parsed into a <see cref="LogEventLevel"/>.
        /// </param>
        /// <exception cref="System.ArgumentNullException">
        /// Thrown if <paramref name="configuration" /> is <see langword="null" />.
        /// </exception>
        /// <exception cref="System.ArgumentOutOfRangeException">
        /// Thrown if <paramref name="updateIntervalMilliseconds" /> is less than <c>1</c>.
        /// </exception>
        /// <remarks>
        /// <para>
        /// The switch uses a background timer to update configuration rather than the
        /// change token/notification system in the configuration because many providers
        /// that aren't file-based (e.g., environment variables) don't have change
        /// notifications built in.
        /// </para>
        /// </remarks>
        public ConfigurableLoggingLevelSwitch(IConfigurationSection configuration, int updateIntervalMilliseconds, LogEventLevel defaultLevel = LogEventLevel.Information)
            : base(defaultLevel)
        {
            if (configuration == null)
            {
                throw new ArgumentNullException(nameof(configuration));
            }

            if (updateIntervalMilliseconds < 1)
            {
                throw new ArgumentOutOfRangeException(nameof(updateIntervalMilliseconds));
            }

            this.Configuration = configuration;
            this.UpdateIntervalMilliseconds = updateIntervalMilliseconds;
            this.UpdateLevel(null);
            this._updateTimer = new Timer(this.UpdateLevel, null, Timeout.Infinite, this.UpdateIntervalMilliseconds);
        }

        /// <summary>
        /// Gets the configuration key used for updating the switch.
        /// </summary>
        /// <value>
        /// The configuration key where the log level is set. The value at this
        /// node will be parsed into a <see cref="LogEventLevel"/> and update
        /// the switch value.
        /// </value>
        public IConfigurationSection Configuration { get; private set; }

        /// <summary>
        /// Gets the interval at which the switch is updated.
        /// </summary>
        /// <value>
        /// The interval at which the <paramref name="configuration" /> should be read
        /// so the <see cref="LoggingLevelSwitch.MinimumLevel"/> can be updated.
        /// </value>
        public int UpdateIntervalMilliseconds { get; private set; }

        /// <summary>
        /// Performs application-defined tasks associated with freeing,
        /// releasing, or resetting unmanaged resources.
        /// </summary>
        public void Dispose()
        {
            this.Dispose(true);
        }

        /// <summary>
        /// Starts the background auto-update process.
        /// </summary>
        public void Start()
        {
            if (this._isDisposed)
            {
                throw new ObjectDisposedException(this.GetType().FullName);
            }

            this._updateTimer.Change(0, this.UpdateIntervalMilliseconds);
        }

        /// <summary>
        /// Stops the background auto-update process.
        /// </summary>
        public void Stop()
        {
            if (this._isDisposed)
            {
                throw new ObjectDisposedException(this.GetType().FullName);
            }

            this._updateTimer.Change(Timeout.Infinite, this.UpdateIntervalMilliseconds);
        }

        /// <summary>
        /// Releases unmanaged and - optionally - managed resources.
        /// </summary>
        /// <param name="disposing">
        /// <see langword="true" /> to release both managed and unmanaged resources;
        /// <see langword="false" /> to release only unmanaged resources.
        /// </param>
        protected virtual void Dispose(bool disposing)
        {
            if (!this._isDisposed)
            {
                if (disposing)
                {
                    this.Stop();
                    this._updateTimer.Dispose();
                }

                this._isDisposed = true;
            }
        }

        /// <summary>
        /// Timer callback that updates the switch level based on the value in configuration.
